import {VERSION,MODEL_VERSION,DATA_VERSION,CROPS,METRICS,SCENARIOS,SOURCES,makeDemo,defaultConfig,selectedFarms,baselineAllocation,toGeoJSON,validateDataset,hash,areaHa,centroid} from './data.js';
import {evaluate,search} from './model.js';
import {FarmMap} from './map.js';
import {climateChart,composition,capacityChart,paretoChart} from './charts.js';
import {esc,fmt,money,uid,now,displayDate,download,csv,icon} from './utils.js';
import {REGIONAL_EVIDENCE_VERSION,ROUTES,OFFICIAL_SNAPSHOT,NUTRIENT_BOUNDARY_STUDY,AUDIT,STATUS,assessStages,auditCsvRows} from './research.js';
import {getLanguage,setLanguage,applyLanguage,observeLanguage} from './i18n.js';
const KEY='farmsystem-workspace-v2',root=document.querySelector('#app'),modal=document.querySelector('#modal');
const PAGES={research:['layers','研究路线','Research routes'],overview:['grid','案例区总览','Case overview'],resources:['map','空间与资源','Spatial resources'],analysis:['chart','系统分析','System analysis'],planner:['sliders','情景规划','Scenario lab'],feedback:['compare','方案与反馈','Plans & feedback'],data:['database','数据中心','Data & provenance'],evidence:['shield','证据与质控','Evidence & quality'],guide:['book','研究说明','Research notes']};
let stored=null;try{stored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
const initial=stored?.dataset&&validateDataset(stored.dataset).length===0?stored.dataset:makeDemo();
let state={dataset:initial,climate:stored?.climate||null,context:null,imagery:null,scope:'region',scopeIds:[],page:location.hash.slice(1) in PAGES?location.hash.slice(1):'research',researchTrack:'province',config:defaultConfig(),selectedPlot:initial.plots[0].id,
 plans:Array.isArray(stored?.plans)?stored.plans:[],observations:Array.isArray(stored?.observations)?stored.observations:[],audit:Array.isArray(stored?.audit)?stored.audit:[],basemap:'satellite',theme:'evidence',opacity:.10,showOSM:false,showAllFields:false,evidence:null,osmPatches:null,allFields:null,release:null,showResources:false,view:null,resourceTab:'plots',query:'',results:null,candidateId:null,preview:null,menu:false,loading:true,running:false,progress:0};
let map=null,worker=null,toastTimer,language=getLanguage();
const farms=()=>selectedFarms(state.dataset,state.scope,state.scopeIds),ids=()=>farms().map(f=>f.id),plots=()=>state.dataset.plots.filter(p=>ids().includes(p.farmId));
const current=()=>evaluate(state.dataset,ids(),baselineAllocation(plots()),state.config,state.climate);
const period=()=>`2025 年 ${state.config.quarter*3+1}–${state.config.quarter*3+3} 月`;
const badge=(kind,label)=>`<span class="tag ${kind}"><i></i>${esc(label)}</span>`;
const provenance=p=>p==='synthetic'?badge('synthetic','虚拟演示'):p==='observed'?badge('local','用户声明实测 · 未核验'):badge('local','用户录入 · 未核验');
const safeUrl=u=>/^https?:\/\//i.test(String(u))?esc(u):'#';
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({schemaVersion:1,dataset:state.dataset,climate:state.climate,plans:state.plans,observations:state.observations,audit:state.audit.slice(0,80)}));state.storageError=false;return true;}catch{state.storageError=true;toast('浏览器存储不足或被禁用。当前更改尚未持久保存，请导出项目包。');return false;}}
function audit(action,detail){state.audit.unshift({id:uid(),at:now(),action,detail});state.audit=state.audit.slice(0,80);return persist();}
function navigate(page){state.page=page;state.menu=false;location.hash=page;render();window.scrollTo(0,0);}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${PAGES[state.page][2]} / FIELD TO SYSTEM</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function warning(){return `<div class="notice">${icon('shield')}<span><strong>研究预览 · v${VERSION}</strong>　公开预测几何与历史气候；经营主体、作物、资源和生产系数仍是假设。未地面核验，不用于确权或实际生产决策。</span><button class="text-link" data-nav="evidence">检查依据 ${icon('arrow')}</button></div>`;}
function stat(label,value,unit,note,kind='synthetic',sym='grid',highlight=false){return `<div class="card stat ${highlight?'highlight':''}"><div class="stat-label">${icon(sym)}${label}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${badge(kind,kind==='public'?'公开网格':kind==='model'?'模型估计':'虚拟 / 本地')}<span>${note}</span></div></div>`;}
function researchProposal(route){if(route!=='province')return '';
 const aims=[
  ['01 / 空间与时间识别','按市县年份建立同口径生产与资源资料，再依据证据划分农业系统类型，识别变化和风险。'],
  ['02 / 跨尺度建模','建立区域活动与资源核算；用有抽样依据的典型农户、农场检查区域措施的经营可行性。'],
  ['03 / 方案与适应','比较分区措施组合、固定策略和可更新策略；先做情景评估，参数与验证充分后再谈优化。']
 ];
 const scales=[
  ['农户','决定劳动、投入和参与条件；记录家庭目标与经营权限。'],
  ['农场','组合地块与生产活动，核算水、养分、劳动和收益。'],
  ['村落','只在明确参与、共享规则与设施边界时比较协作方案。'],
  ['海南','以市县／分区为分析单元，汇总差异、比较政策与资源情景。']
 ];
 return `<section class="research-proposal"><div class="research-section-head"><div><span class="research-index">路线二 / 讨论版方案</span><h2>海南农业系统的跨尺度适应性规划</h2><p>研究主张：先识别区域差异，再连接典型经营系统，最后比较有权限与资源边界的分区措施组合。</p></div><span>构思草案 · 未实施</span></div><div class="research-aims">${aims.map(([name,description])=>`<article><h3>${esc(name)}</h3><p>${esc(description)}</p></article>`).join('')}</div><div class="research-example"><strong>示例情景：旱季水资源约束</strong><p>在适宜地区比较现状、节水管理与种植组合调整；保持不可即时改变的多年生作物和经营权边界。比较产出、收益、水需求及主体参与条件，并在典型农场检查措施是否可做。此处是待检验设计，没有计算结果。</p></div><div class="research-section-head scale-heading"><div><h2>通用平台：四级尺度，同一证据链</h2><p>地理范围、实际决策者、数据粒度和模型适用范围分别记录；海南是区域汇总与协调层，不是一个经营主体。</p></div></div><div class="research-scales">${scales.map(([name,description])=>`<article><h3>${esc(name)}</h3><p>${esc(description)}</p></article>`).join('')}</div><p class="research-linkage">连接规则：地块关联经营主体与行政单元；典型主体只有在选样、类型和权重明确后才参与区域推断。各尺度共用活动、资源、情景和结果词典，模型与验证仍按尺度分别管理。</p><a class="research-plan-link" href="./docs/RESEARCH_ROUTES.md" target="_blank" rel="noopener noreferrer">阅读完整研究与平台设计 ↗</a></section>`;
}
function nutrientEvidence(){const study=NUTRIENT_BOUNDARY_STUDY;return `<section class="research-nutrient-evidence"><div class="research-section-head"><div><span class="research-index">已核读文献 · 尚未接入模型</span><h2>${esc(study.title)}</h2><p>${esc(study.method)}；历史 ${esc(study.history)}，情景 ${esc(study.scenarios)}。</p></div><span>${esc(study.geography)}</span></div><div class="research-nutrient-values">${study.evidence.map(item=>`<div><small>${esc(item.label)}</small><strong>${esc(item.value)}</strong><span>${esc(item.unit)}</span><small>${esc(item.source)}</small></div>`).join('')}</div><p class="research-nutrient-boundary">${icon('shield')}<span>${esc(study.boundary)}</span></p><a href="${safeUrl(study.url)}" target="_blank" rel="noopener noreferrer">${esc(study.citation)} ↗</a></section>`;}
function researchPage(){const route=state.researchTrack,info=ROUTES[route],rows=AUDIT.filter(row=>row.track===route),stages=assessStages(route),sourceCount=rows.filter(row=>['source-confirmed','display-only'].includes(row.status)).length;
 const snapshot=route==='province'?`<section class="research-snapshot"><div class="research-section-head"><div><h2>海南省年度背景</h2><p>省级统计值用于认识总体规模，不进入当前农场模型，也不拆分成市县估计。</p></div><span>${OFFICIAL_SNAPSHOT.year} · ${OFFICIAL_SNAPSHOT.geography}</span></div><div class="research-kpis">${OFFICIAL_SNAPSHOT.values.map(v=>`<div><small>${esc(v.label)}</small><strong>${fmt(v.value,2)}</strong><span>${esc(v.unit)}</span></div>`).join('')}</div><a href="${safeUrl(OFFICIAL_SNAPSHOT.url)}" target="_blank" rel="noopener noreferrer">来源：${esc(OFFICIAL_SNAPSHOT.source)} · ${OFFICIAL_SNAPSHOT.published} ↗</a></section>`:`<section class="research-snapshot farm-snapshot"><div class="research-section-head"><div><h2>当前案例原型</h2><p>崖州附近的局部演示窗口与海南全域统计资料分库存放。</p></div><span>v${VERSION} · 模型 ${MODEL_VERSION}</span></div><div class="research-case-facts"><div><strong>${state.dataset.plots.length}</strong><span>预测空间单元</span></div><div><strong>${state.dataset.farms.length}</strong><span>虚拟经营主体</span></div><div><strong>0</strong><span>已核验真实农户</span></div></div><button class="primary" data-nav="overview">打开案例区工作台 ${icon('arrow')}</button></section>`;
 return heading('两条研究路线，一套证据边界。','保留 Topic 6 的农场系统设计主线，同时准备海南全域的区域研究方案；研究尺度和模型结论分别核验。')+`<div class="research-pending">${icon('info')}<div><strong>课题尺度尚待 导师组确认</strong><p>海南全域方向仍在讨论中。这里并列保留两条研究路线；路线二是讨论方案，尚非已经批准的正式课题变更。</p></div></div><div class="research-switch" role="group" aria-label="选择研究路线">${Object.entries(ROUTES).map(([key,r])=>`<button data-research-track="${key}" aria-pressed="${route===key}" class="${route===key?'active':''}"><span>${esc(r.status)}</span><strong>${esc(r.title)}</strong><small>${esc(r.unit)}</small></button>`).join('')}</div><div class="research-intro"><div><span class="research-index">研究问题 / ${route==='farm'?'01':'02'}</span><h2>${esc(info.question)}</h2><p>决策单元：${esc(info.unit)}</p></div><div><span class="research-index">预期研究产出</span><ol>${info.outputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></div><p class="research-boundary">${icon('shield')}<span>${esc(info.boundary)}</span></p>${researchProposal(route)}${snapshot}${route==='province'?nutrientEvidence():''}<div class="research-section-head stage-heading"><div><h2>数据就绪关口</h2><p>只有数据已接入并核验，阶段才显示就绪。确认来源、拥有地图或通过软件测试均不算科学验证。</p></div><span>${sourceCount} 项来源已核对 · ${stages.filter(x=>x.ready).length}/${stages.length} 阶段就绪</span></div><div class="research-stages">${stages.map((stage,i)=>`<article><span>0${i+1} / ${stage.ready?'已就绪':'待数据'}</span><h3>${esc(stage.name)}</h3><p>${stage.ready?'所有前置资料已接入并核验。':`缺少 ${stage.missing.length} 项已核验前置资料：${stage.missing.map(id=>esc(AUDIT.find(row=>row.id===id)?.name||id)).join('、')}。`}</p></article>`).join('')}</div><div class="research-section-head audit-heading"><div><h2>逐项数据审计</h2><p>这里记录来源状态、时空粒度和缺口；下载表格后可与导师逐项核对。</p></div><button data-action="export-research-audit">${icon('download')}导出本路线清单</button></div><div class="research-audit card"><div class="table-wrap"><table><thead><tr><th>数据主题</th><th>当前状态</th><th>时空粒度 / 时期</th><th>用于回答</th><th>仍需完成</th><th>来源</th></tr></thead><tbody>${rows.map(row=>`<tr><td><strong>${esc(row.name)}</strong></td><td><span class="audit-status ${row.status}">${esc(STATUS[row.status])}</span></td><td>${esc(row.grain)}<small>${esc(row.period)}</small></td><td>${esc(row.use)}</td><td>${esc(row.gap)}</td><td>${row.url?`<a href="${safeUrl(row.url)}" target="_blank" rel="noopener noreferrer">查看 ↗</a>`:'待定'}</td></tr>`).join('')}</tbody></table></div></div><section class="research-decisions"><h2>需要导师组明确的三项决定</h2><div><p><b>01</b> PhD2 的主要决策单元：农场系统、市县／分区，或两者如何连接？</p><p><b>02</b> 原 proposal 中的农场模型、数字孪生与 PhD1 协作保留到什么程度？</p><p><b>03</b> 全域路线的目标是诊断、情景评估，还是有独立参数与验证支撑的优化？</p></div><a href="./docs/RESEARCH_ROUTES.md" target="_blank" rel="noopener noreferrer">查看完整路线设计与验收边界 ↗</a></section>`;
}
function scopeBar(){const fs=farms(),d=state.dataset;let control='';
 if(state.scope==='village')control=`<select id="scope-object" aria-label="选择村落">${d.villages.map(v=>`<option value="${esc(v.id)}" ${state.scopeIds.includes(v.id)?'selected':''}>${esc(v.name)}</option>`).join('')}</select>`;
 if(state.scope==='single')control=`<select id="scope-object" aria-label="选择经营主体">${d.farms.map(f=>`<option value="${esc(f.id)}" ${state.scopeIds.includes(f.id)?'selected':''}>${esc(f.name)}</option>`).join('')}</select>`;
 if(state.scope==='group')control=`<button class="small" data-action="select-group">${icon('people')}选择成员（${fs.length}）</button>`;
 return `<div class="scope-bar"><span class="scope-label">${icon('layers')}分析范围</span><select id="scope" aria-label="分析范围">${[['region','整个证据窗口'],['village','单个协作组（假设）'],['single','单个农户 / 农场'],['group','若干农户 / 农场'],['typical','典型主体（假设案例）']].map(([v,n])=>`<option value="${v}" ${state.scope===v?'selected':''}>${n}</option>`).join('')}</select>${control}<span class="scope-summary">${fs.length} 个主体 · ${plots().length} 个空间单元</span><div class="period">${icon('clock')}模型窗口<select id="quarter" aria-label="模型季度">${[0,1,2,3].map(q=>`<option value="${q}" ${q===state.config.quarter?'selected':''}>2025 Q${q+1} · ${q*3+1}–${q*3+3}月</option>`).join('')}</select></div></div>`;
}
function mapCard(large=false){return `<section class="card map-card studio-map"><div class="map-toolbar"><div class="segmented" aria-label="地图底图">${[['satellite','Sentinel-2 · 10 m'],['context','本地矢量'],['osm','在线 OSM']].map(([v,n])=>`<button data-basemap="${v}" class="${state.basemap===v?'active':''}">${n}</button>`).join('')}</div><div class="map-theme-control"><span>专题</span><select id="map-theme" aria-label="地图着色方式">${[['evidence','空间边界证据'],['area','几何面积'],['activity','假设生产活动'],['owner','假设经营分组']].map(([v,n])=>`<option value="${v}" ${state.theme===v?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="farm-map ${large?'large':''}" id="farm-map"></div><div class="map-evidence-footer"><span>${icon('clock')}影像 2025-03-22 · 历史快照</span><span class="resolution-note">原始分辨率 10 m · 放大不增加精度</span><label>叠加<input id="map-opacity" type="range" min="0" max="35" value="${Math.round(state.opacity*100)}" aria-label="单元填充透明度"></label></div><div class="map-layer-bar"><label><input type="checkbox" id="show-osm" ${state.showOSM?'checked':''}>OSM 农业斑块参照</label><label><input type="checkbox" id="show-all-fields" ${state.showAllFields?'checked':''}>全部已下载预测单元</label><span>两者均非地籍</span></div>${state.theme==='activity'||state.preview?`<div class="map-legend">${Object.values(CROPS).map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join('')}<span class="disclaimer">假设活动 · 不代表实际种植</span></div>`:''}</section>`;}
function plotSilhouette(p){const points=p.geometry.coordinates[0],xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),mx=Math.min(...xs),my=Math.min(...ys),dx=Math.max(...xs)-mx,dy=Math.max(...ys)-my,scale=Math.min(90/(dx||1),62/(dy||1));return `<svg viewBox="0 0 110 82" class="plot-silhouette" aria-label="源边界形状缩略图"><defs><pattern id="mini-grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M10 0H0V10" fill="none" stroke="#b6cfc5" stroke-width=".35"/></pattern></defs><rect width="110" height="82" fill="url(#mini-grid)"/><path d="${p.geometry.coordinates.map(r=>r.map((v,i)=>`${i?'L':'M'}${10+(v[0]-mx)*scale},${72-(v[1]-my)*scale}`).join(' ')+'Z').join(' ')}" fill="#71b59b25" stroke="#549e86" stroke-width="1.2" fill-rule="evenodd"/></svg>`;}
function plotDetail(){const p=state.dataset.plots.find(p=>p.id===state.selectedPlot)||plots()[0];if(!p)return '<section class="card empty">未选择空间单元</section>';const f=state.dataset.farms.find(f=>f.id===p.farmId),c=CROPS[state.preview?.candidate?.allocation?.[p.id]||p.crop],xy=centroid(p),pred=p.geometrySource==='public-ml-prediction';
 return `<section class="card detail-card inspector"><div class="inspector-top"><span class="eyebrow">OBJECT INSPECTOR</span><b class="mono">${esc(p.id)}</b></div><div class="inspector-title"><div><h2>${esc(p.name)}</h2>${badge(pred?'public':'local',pred?'公开预测几何':'用户几何 · 未核验')}<small class="mono">${pred?'FTW 2025 / ':''}${esc(p.sourceId||p.id)}</small></div>${plotSilhouette(p)}</div><div class="area-reading"><strong>${fmt(p.areaHa,2)}</strong><span>ha<small>${fmt(p.areaHa*15,2)} 亩</small></span><button data-action="focus-plot" class="square" aria-label="定位选中单元">${icon('map')}</button></div><div class="inspector-section"><h3><span>01</span> 空间证据</h3><dl class="evidence-dl"><div><dt>几何来源</dt><dd>${pred?'遥感模型预测 · 非地籍':'用户资料 · 未核验'}</dd></div><div><dt>边界处理</dt><dd>${pred?'保留源顶点与孔洞':'按导入数据保留'}</dd></div><div><dt>面积口径</dt><dd>${pred?'WGS84 椭球计算':'按导入声明，近似核对'}</dd></div><div><dt>质量值 / 覆盖层</dt><dd>${p.sourceConfidence===null||p.sourceConfidence===undefined?'缺失，不补造':esc(p.sourceConfidence)+' · 非概率'}</dd></div><div><dt>实际作物 / 经营者</dt><dd class="unknown">未知 · 待调查</dd></div></dl></div><div class="inspector-section"><h3><span>02</span> 建模假设 <em>不代表现状</em></h3><div class="assumption-box"><dl class="evidence-dl"><div><dt>模拟决策主体</dt><dd>${esc(f.name)}</dd></div><div><dt>${state.preview?'方案活动':'假设基准活动'}</dt><dd><i class="crop-dot" style="background:${c.color}"></i>${c.name}</dd></div><div><dt>产出因子 / 无实测土壤</dt><dd>${fmt(p.soilFactor,2)}</dd></div></dl></div></div><div class="detail-actions"><button data-action="edit-plot" data-id="${esc(p.id)}">${icon('edit')}修改假设</button><button class="primary" data-action="plan-farm" data-id="${esc(f.id)}">分析 ${icon('arrow')}</button></div><div class="inspector-bottom"><a href="${safeUrl(p.sourceUrl||SOURCES.repository)}" target="_blank" rel="noreferrer">查看源产品 ↗</a><small class="mono">${fmt(xy[0],4)} E / ${fmt(xy[1],4)} N</small></div></section>`;}
function overviewPage(){const area=plots().reduce((a,p)=>a+p.areaHa,0);return heading('从真实空间，开始系统设计。','用可追溯的空间证据建立底座，在明确的假设下比较安排。',`<button class="primary" data-nav="planner">${icon('sliders')}进入情景实验室</button>`)+scopeBar()+`<div class="evidence-ribbon"><div><i class="tiny-dot"></i><strong>${plots().length}</strong> 空间单元（${plots().filter(p=>p.geometrySource==='public-ml-prediction').length} 个公开预测） <span>·</span> ${fmt(area,2)} ha <span>·</span> 原始边界未重画</div><div><i class="tiny-dot amber"></i>经营属性为假设 <span>·</span> 尚无地面核验 <button class="text-link" data-nav="evidence">证据与限制 ${icon('arrow')}</button></div></div><div class="studio-grid">${mapCard()}<div id="object-inspector">${plotDetail()}</div></div><div class="overview-lower"><section class="card climate-card"><div class="card-header"><div><div class="eyebrow">TEMPORAL CONTEXT / 2025</div><h2>理解季节，而不是伪造实时。</h2></div>${badge('public','NASA POWER')}</div>${climateChart(state.climate,state.config.quarter)}<p class="micro">区域网格气象 · 仅降水接入需水核算 · 与田块实测分开记录</p></section><section class="card evidence-intro"><div class="eyebrow">EVIDENCE + ASSUMPTION + EXPLORATION</div><h2>哪些已知，哪些仍需调查？</h2><div class="knowledge-row"><i class="tiny-dot"></i><span>公开边界来源与历史影像</span><b>可追溯</b></div><div class="knowledge-row"><i class="tiny-dot unknown-dot"></i><span>真实田界、作物、经营权、土壤</span><b>待核验</b></div><div class="knowledge-row"><i class="tiny-dot amber"></i><span>生产系数、资源配额、协作分组</span><b>假设</b></div><p>边界来自公开模型预测，不等于实测田界。110 个单元是规则筛选的演示集合，不代表当地全部农田。</p><button class="text-link" data-nav="evidence">逐项检查数据证据 ${icon('arrow')}</button></section></div>`;}
function plotTable(){const query=state.query.toLowerCase(),ps=plots().filter(p=>`${p.id} ${p.name} ${p.farmId} ${CROPS[p.crop].name}`.toLowerCase().includes(query));return `<div class="table-wrap"><table><thead><tr><th>地块 / 编号</th><th>经营主体</th><th>活动</th><th>面积 ha</th><th>几何身份</th><th>调整边界</th><th>操作</th></tr></thead><tbody>${ps.map(p=>`<tr class="${p.id===state.selectedPlot?'selected-row':''}"><td><button class="text-link" data-action="select-plot" data-id="${esc(p.id)}">${esc(p.name)} <small class="mono">${esc(p.id)}</small></button></td><td>${esc(p.farmId)}</td><td><i class="crop-dot" style="background:${CROPS[p.crop].color}"></i>${CROPS[p.crop].name}</td><td class="number">${fmt(p.areaHa,3)}</td><td>${p.geometrySource==='public-ml-prediction'?badge('public','公开预测边界'):provenance(p.geometrySource)}</td><td>${p.locked||!CROPS[p.crop].annual?'固定':'可调整'}</td><td><button class="small subtle" data-action="edit-plot" data-id="${esc(p.id)}">编辑</button></td></tr>`).join('')||'<tr><td colspan="7">没有匹配的地块。</td></tr>'}</tbody></table></div>`;}
function farmTable(){const fs=farms().filter(f=>`${f.name} ${f.id}`.toLowerCase().includes(state.query.toLowerCase()));return `<div class="table-wrap"><table><thead><tr><th>经营主体</th><th>虚拟分组</th><th>地块数</th><th>三个月水配额 m³</th><th>劳动配额 工日</th><th>家禽 只</th><th>身份 / 操作</th></tr></thead><tbody>${fs.map(f=>`<tr><td>${esc(f.name)} <small class="mono">${esc(f.id)}</small></td><td>${esc(f.villageId)}</td><td>${state.dataset.plots.filter(p=>p.farmId===f.id).length}</td><td class="number">${fmt(f.water.reduce((a,b)=>a+b,0))}</td><td class="number">${fmt(f.labour.reduce((a,b)=>a+b,0))}</td><td class="number">${f.poultry}</td><td>${provenance(f.provenance)} <button class="small subtle" data-action="edit-farm" data-id="${esc(f.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div>`;}
function resourcesPage(){return heading('把资源与经营主体连接起来','空间归属不等于统一经营。先识别对象，再明确谁能够调配哪些资源。',`<button data-action="export-geojson">${icon('download')}导出地块</button>`)+scopeBar()+(state.preview?`<div class="notice info" style="margin-bottom:17px">${icon('info')}<span>正在查看方案「${esc(state.preview.name)}」。${badge('model','情景预览')} 未覆盖当前生产记录。</span><button class="small" data-action="exit-preview">退出预览</button></div>`:'')+`<div class="cols">${mapCard(true)}<div class="stack">${plotDetail()}<section class="card"><div class="card-header"><h3>关系图层</h3>${badge('synthetic','假设关系')}</div><label class="row" style="font-size:12px"><input type="checkbox" id="show-resources" ${state.showResources?'checked':''}>显示假设主体与空间单元的关联</label><p class="micro">仅用于表达资源关系，关系锚点不是实测设施，不是水渠线路、管网、水权或水力学模型。相同地理范围可以采用不同决策规则。</p><button data-nav="analysis" class="text-link" style="margin-top:15px">查看资源核算 ${icon('arrow')}</button></section></div></div><section class="card" style="margin-top:18px"><div class="card-header"><div class="tabs" style="margin:0;border:0"><button data-resource-tab="plots" class="${state.resourceTab==='plots'?'active':''}">地块档案</button><button data-resource-tab="farms" class="${state.resourceTab==='farms'?'active':''}">经营主体</button></div><div class="search-field">${icon('search')}<input id="resource-search" value="${esc(state.query)}" placeholder="编号、名称或活动…" aria-label="搜索资源"></div></div><div id="resource-table">${state.resourceTab==='plots'?plotTable():farmTable()}</div></section>`;}
function decisionSelect(){return `<select id="decision-mode" aria-label="决策组织模式"><option value="independent" ${state.config.mode==='independent'?'selected':''}>逐户独立规划</option><option value="cooperative" ${state.config.mode==='cooperative'?'selected':''}>同村自愿协作情景</option><option value="centralized" ${state.config.mode==='centralized'?'selected':''}>所选范围集中协调假设</option></select>`;}
function analysisPage(){const e=current(),t=e.totals;return heading('看清约束，再讨论更好的方案','同一组地块，采用不同资源边界会产生不同的可行空间。',`<button class="primary" data-nav="planner">${icon('sliders')}进入情景规划</button>`)+scopeBar()+warning()+`<div class="row wrap" style="margin-top:16px"><span class="muted" style="font-size:11px">资源核算规则</span>${decisionSelect()}${badge(e.feasible?'public':'danger',e.feasible?'当前基准通过资源检查':'当前基准存在约束超限')}<span class="micro">${period()} · 所有生产系数为演示值</span></div><div class="stats">${stat('核算收益',money(t.margin),'元','未计土地租金与固定资产折旧','model','chart')}${stat('灌溉 / 补水需求',fmt(t.water),'m³',`配额 ${fmt(t.waterCapacity)} m³`,'model','drop')}${stat('劳动需求',fmt(t.labour),'工日',`配额 ${fmt(t.labourCapacity)} 工日`,'model','people')}${stat('系统氮收支余量',fmt(t.nSurplus),'kg N','包含存量变化与损失，非排放量','model','leaf')}</div>${!e.feasible?`<div class="notice error" style="margin-bottom:17px">${icon('info')}<span>基准的投入需求未全部满足，产出和收益仅为未受约束的核算值，不代表可实现结果。${esc(e.violations.slice(0,4).join('；'))}${e.violations.length>4?`；另 ${e.violations.length-4} 项`:''}。</span></div>`:''}<div class="cols equal"><section class="card"><div class="card-header"><div><h2>逐月用水需求</h2><p>公开降雨进入需求核算，供水能力仍为虚拟</p></div>${badge('model','约束检查')}</div>${capacityChart(e.balances,'水')}</section><section class="card"><div class="card-header"><div><h2>逐月劳动需求</h2><p>月度总量可行仍不保证日内排程可行</p></div>${badge('model','约束检查')}</div>${capacityChart(e.balances,'劳动')}</section></div><section class="card" style="margin-top:18px"><div class="card-header"><div><h2>资源如何在系统中流动</h2><p>种植、固定家禽与水产的简化氮收支；系统内转移不重复计作外部投入</p></div>${badge('model','可追溯核算')}</div><div class="flow-grid"><div class="flow-node"><small>外部输入 N</small><b>${fmt(t.nInput)} kg</b><small>矿质肥 + 外购饲料 + 生物固氮</small></div><div class="flow-arrow">${icon('arrow')}</div><div class="flow-node"><small>内部粪肥循环 N</small><b>${fmt(t.manureApplied)} kg</b><small>含65%回收率、45%当季有效率假设</small></div><div class="flow-arrow">${icon('arrow')}</div><div class="flow-node"><small>产品带出 N</small><b>${fmt(t.nOutput)} kg</b><small>作物产品 + 畜禽产品 + 水产品</small></div><div class="flow-arrow">${icon('arrow')}</div><div class="flow-node"><small>收支余量 N</small><b>${fmt(t.nSurplus)} kg</b><small>输入 − 产品输出 ≠ 直接排放</small></div></div><p class="flow-note">当前配置：矿质肥氮 ${fmt(t.chemicalN)} kg；粪肥产生氮 ${fmt(t.manureProduced)} kg、回收氮 ${fmt(t.manureRecovered)} kg。未进入田间的粪肥保留在系统余量中。未选主体的 ${fmt(e.boundary.outsideReservedWater)} m³ 水配额没有被调用。</p>${e.transfers.length?`<div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>提供者</th><th>接收者</th><th>资源</th><th>转移量 kg N</th></tr></thead><tbody>${e.transfers.map(x=>`<tr><td>${esc(x.from)}</td><td>${esc(x.to)}</td><td>${x.resource} · 假设联系</td><td>${fmt(x.quantity,2)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="note-block">当前配置下没有发生跨户粪肥转移。这是计算结果，不预先假定协作一定有收益。</div>`}</section><section class="card" style="margin-top:18px"><div class="card-header"><h2>整体之外，也看每一个经营主体</h2><button class="small" data-action="export-baseline">${icon('download')}导出核算</button></div>${farmResultsTable(e)}<p class="micro">可食能量为演示系数换算，并非已评估的食物保障；劳动负担及参与收益底线只覆盖部分社会可接受性问题。</p></section>`;}
function farmResultsTable(e,baseline=null){return `<div class="table-wrap"><table><thead><tr><th>经营主体</th><th>面积 ha</th><th>核算收益 元</th>${baseline?'<th>较基准变化 元</th>':''}<th>用水 m³</th><th>劳动 工日</th><th>矿质肥 kg N</th><th>氮余量 kg N</th><th>能量 GJ</th></tr></thead><tbody>${e.farms.map(f=>{const b=baseline?.farms.find(x=>x.id===f.id),delta=b?f.margin-b.margin:null;return `<tr><td>${esc(f.name)}</td><td class="number">${fmt(f.area,2)}</td><td class="number">${fmt(f.margin)}</td>${baseline?`<td class="number ${delta<0?'delta bad':'delta'}">${delta>=0?'+':''}${fmt(delta)}</td>`:''}${['water','labour','chemicalN','nSurplus','energy'].map(k=>`<td class="number">${fmt(f[k])}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;}
function rangeControl(id,name,value){return `<div class="field"><div class="range-label"><label for="${id}">${name}</label><output id="${id}-value">${fmt(value*100)}%</output></div><input type="range" id="${id}" data-config="${id}" min="0" max="200" step="5" value="${Math.round(value*100)}"></div>`;}
function stale(){const r=state.results;return r&&r.inputHash!==hash({data:state.dataset,farmIds:ids(),config:state.config,climate:state.climate});}
function plannerPage(){const c=state.config,r=state.results;return heading('把“可能怎样”变成可比较的方案','只改变情景，不改写现实。搜索可行组合，检查资源约束与收益分配。',`<button data-action="export-results" ${!r?'disabled':''}>${icon('download')}导出本次计算</button>`)+scopeBar()+`<div class="planner-layout"><aside class="card controls"><div class="card-header"><h2>情景实验室</h2>${badge('model','非全局最优')}</div><div class="field"><label>决策规则</label>${decisionSelect()}</div><p class="micro" id="mode-note">${c.mode==='independent'?'每户独立水 / 劳动 / 粪肥边界，不允许借用其他主体配额。':c.mode==='cooperative'?'仅在所选同村成员之间共享资源；跨村仍分开。协作需要现实同意。':'假设所选主体可统一协调。它是比较情景，不意味着存在统一管理权。'}</p><div class="scenario-chips">${Object.entries(SCENARIOS).map(([k,v])=>`<button data-scenario="${k}" class="${c.scenario===k?'active':''}">${v.name}</button>`).join('')}</div><div class="controls-grid">${rangeControl('water','可用水配额',c.water)}${rangeControl('labour','可用劳动配额',c.labour)}${rangeControl('rain','降雨情景倍率',c.rain)}${rangeControl('price','蔬菜价格倍率',c.price)}</div><p class="micro">倍率只用于当前情景；没有修改 NASA 原始降水数据。生产冲击系数 ${fmt(c.shock,2)} 为预设演示假设。</p><hr class="divider"><div class="field"><label for="objective">方案排序偏好</label><select id="objective"><option value="balanced" ${c.objective==='balanced'?'selected':''}>综合偏好 · 权重可查</option><option value="income" ${c.objective==='income'?'selected':''}>优先核算收益</option><option value="water" ${c.objective==='water'?'selected':''}>优先降低用水</option><option value="environment" ${c.objective==='environment'?'selected':''}>优先降低氮余量绝对值</option><option value="food" ${c.objective==='food'?'selected':''}>优先可食能量代理</option></select></div><div class="field"><label for="participation">每户收益参与底线</label><select id="participation">${[[0,'不设底线（显示利益差异）'],[.8,'相对基准最多下降20%'],[1,'任何成员收益不得下降']].map(([v,n])=>`<option value="${v}" ${c.minIncomeRatio===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="primary run" data-action="run" ${state.running?'disabled':''}>${icon('play')}${state.running?'正在搜索…':'运行方案搜索'}</button>${state.running?`<div class="progress"><span style="width:${state.progress}%"></span></div><button class="subtle small" data-action="cancel-run">取消计算</button>`:''}<p class="micro">固定种子 ${c.seed} · 年生作物候选4类 · 果园 / 水产固定 · 最多约1600随机候选 + 局部搜索。小问题完整枚举。</p></aside><div class="stack">${stale()?`<div class="notice error">${icon('info')}<span>当前参数 / 数据 / 范围已变化。下方仍是上次运行的快照，请重新运行后比较；旧方案不会被冒充为最新结果。</span></div>`:''}${r?resultsPanel(r):`<section class="card"><div class="empty">${icon('sliders')}<h3>先选定边界，再开始一次实验</h3><p>用左侧设置改变资源条件。系统会检查逐月水、劳动与固定活动约束，并在可行候选中寻找不同目标的权衡。</p><button class="primary" data-action="run">${icon('play')}运行基准条件下的搜索</button></div><div class="guide-steps"><div class="guide-step"><b>01</b><h3>明确边界</h3><p>选择主体及是否允许协作</p></div><div class="guide-step"><b>02</b><h3>设定变化</h3><p>水、劳动、雨量及价格</p></div><div class="guide-step"><b>03</b><h3>比较权衡</h3><p>查看收益与资源的代价</p></div><div class="guide-step"><b>04</b><h3>保存快照</h3><p>不覆盖现状，保留输入版本</p></div></div></section>`}<section class="card"><h3>这一版的模型边界</h3><p class="micro">生产系数未经田间校准。采用季度内3个月资源核算，不包含连续轮作、作物生长机理、逐日排程、水力过程和完整生命周期环境评价。季度切换是独立情景，不是已实现动态状态传递。可食能量与氮余量是代理指标，不等同完整食物保障或环境影响。</p><button class="text-link" style="margin-top:10px" data-nav="guide">查看公式、约束与扩展接口 ${icon('arrow')}</button></section></div></div>`;}
function resultsPanel(r){const selected=r.candidates.find(x=>x.id===state.candidateId)||r.candidates[0];if(!selected)return `<section class="card"><div class="empty">${icon('info')}<h3>${r.exact?'当前离散候选集没有可行方案':'本次搜索没有找到可行方案'}</h3><p>${r.evaluated} 个已检验候选。${r.exact?'':'这不证明真实问题无解。'}可以调整资源约束、参与底线或选定范围。</p></div><div class="notice error">${icon('info')}<span>${esc(r.bestInfeasible?.violations?.slice(0,8).join('；')||'请检查输入。')}</span></div></section>`;
 const t=selected.totals,b=r.baseline.totals,diff=t.margin-b.margin;return `<section class="card"><div class="result-head"><h2>候选方案的权衡空间</h2>${badge('public',`${r.feasibleCount} 个可行`)}<p>已检验 ${r.evaluated} · ${r.frontierCount} 个非支配候选</p></div>${paretoChart(r,selected.id)}<div class="result-metrics"><div class="result-metric"><label>核算收益 · 元</label><b>${money(t.margin)}</b><span class="delta ${diff<0?'bad':''}">${diff>=0?'+':''}${fmt(diff)} 元 vs 同情景基准</span></div><div class="result-metric"><label>灌溉 / 补水 · m³</label><b>${fmt(t.water)}</b><small>基准 ${fmt(b.water)} m³</small></div><div class="result-metric"><label>氮收支余量 · kg N</label><b>${fmt(t.nSurplus)}</b><small>不是直接环境排放</small></div></div><div class="row wrap"><button class="primary" data-action="save-plan" ${stale()?'disabled':''}>${icon('plus')}保存此方案快照</button><button data-action="preview-candidate">${icon('map')}在地图上查看</button>${badge('model','结果未实测校准')}</div><p class="micro">${r.baseline.feasible?'基准与候选均在相同情景下计算。':'注意：同情景基准存在资源超限，其名义产出不保证可实现。'} ${r.method}。综合排序为收益45%、节水20%、氮余量15%、能量20%，归一化范围仅来自本次候选集；不是客观唯一答案。</p><div class="status-line"><span class="mono">INPUT ${r.inputHash} · MODEL ${r.modelVersion}</span><span>${displayDate(r.createdAt)}</span></div></section><section class="card"><div class="card-header"><h2>可行方案明细</h2><span class="micro">点击一行切换查看</span></div><div class="table-wrap"><table><thead><tr><th>候选</th><th>收益 元</th><th>用水 m³</th><th>劳动 工日</th><th>氮余量 kg N</th><th>能量 GJ</th></tr></thead><tbody>${r.candidates.map((x,i)=>`<tr data-candidate="${esc(x.id)}" class="${selected.id===x.id?'selected-row':''}" style="cursor:pointer"><td><button class="text-link" data-candidate="${esc(x.id)}">方案 ${String(i+1).padStart(2,'0')}</button></td>${['margin','water','labour','nSurplus','energy'].map(k=>`<td class="number">${fmt(x.totals[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-header"><h2>当前候选 · 每户变化</h2>${badge('model','不只看整体')}</div>${farmResultsTable(selected,r.baseline)}<div class="note-block">收入敏感性演示：仅将产品收入乘以 0.8 / 1.2，成本不变时，核算收益为 <strong>${money(selected.sensitivity.lowMargin)}–${money(selected.sensitivity.highMargin)} 元</strong>。这是确定性敏感性区间，不是统计置信区间，也不是经验证的风险预测。</div></section>`;}
function feedbackPage(){const ps=state.plans;const left=ps.find(p=>p.id===state.compareLeft)||ps[0],right=ps.find(p=>p.id===state.compareRight)||ps[1];return heading('让方案留下来，让结果回得来','方案、实施意向与反馈分别记录；保存方案不会改变当前地块的生产活动。',`<button class="primary" data-action="add-observation">${icon('plus')}记录一次反馈</button>`)+`<div class="notice info" style="margin-bottom:18px">${icon('shield')}<span>所有更改只保存在此浏览器中，不会自动写回 GitHub，也不会同步给其他成员。请定期导出项目包。</span></div><div class="cols"><section class="card"><div class="card-header"><div><h2>方案库</h2><p>保留计算时的数据、参数、范围与模型版本</p></div>${badge('model',`${ps.length} 个快照`)}</div>${ps.length?`<div class="panel-list">${ps.map(p=>`<div class="panel-item" style="display:block"><div class="row between wrap"><h3>${esc(p.name)}</h3>${badge(p.status==='intended'?'local':'model',p.status==='intended'?'拟采用 · 非实施证明':'候选快照')}</div><p class="micro">${displayDate(p.createdAt)} · ${p.farmIds.length} 个主体 · ${esc(p.config.mode)} · 2025 Q${p.config.quarter+1}<br><span class="mono">INPUT ${esc(p.inputHash)} / MODEL ${esc(p.modelVersion)}</span></p><div class="row wrap" style="margin:10px 0"><strong>${money(p.candidate.totals.margin)} 元</strong><span class="micro">${fmt(p.candidate.totals.water)} m³ · ${fmt(p.candidate.totals.labour)} 工日</span></div><div class="row wrap"><button class="small" data-action="preview-plan" data-id="${esc(p.id)}">${icon('map')}地图</button><button class="small" data-action="intent-plan" data-id="${esc(p.id)}">${p.status==='intended'?'取消拟采用':'标记拟采用'}</button><button class="small subtle" data-action="export-plan" data-id="${esc(p.id)}">${icon('download')}导出</button><button class="small subtle danger" data-action="delete-plan" data-id="${esc(p.id)}">删除</button></div></div>`).join('')}</div>`:`<div class="empty">${icon('compare')}<h3>还没有保存方案</h3><p>完成一次搜索，选中候选方案，再点击“保存此方案快照”。</p><button data-nav="planner">进入情景规划</button></div>`}</section><section class="card"><div class="card-header"><div><h2>反馈记录</h2><p>用户录入不自动成为经核验的实测数据</p></div>${badge('local',`${state.observations.length} 条`)}</div>${state.observations.length?`<div class="timeline">${state.observations.map(o=>`<div class="timeline-item"><h4>${esc(o.metric==='water'?'窗口用水量':'窗口销售收入')} · ${fmt(o.value)} ${o.metric==='water'?'m³':'元'} ${provenance(o.provenance)}</h4><p>${esc(o.planName)} · ${esc(o.period)}<br>${esc(o.note)}${Number.isFinite(o.predicted)?`<br>对应模型值 ${fmt(o.predicted)}；差值 ${fmt(o.value-o.predicted)}（仅同边界 / 同口径时可比较）`:''}</p><small>结果日期 ${esc(o.date)} · 录入 ${displayDate(o.recordedAt)}</small></div>`).join('')}</div>`:`<div class="empty">${icon('clock')}<h3>等待现实信息进入系统</h3><p>记录日期、来源与统计边界。没有实际结果时，可以选择“虚拟反馈”练习流程，不能冒充已实施。</p></div>`}</section></div>${left&&right?`<section class="card" style="margin-top:18px"><div class="card-header"><div><h2>两个方案，放在一起看</h2><p>不同范围、季节、输入或模型版本的结果不能直接解释为策略效果</p></div></div><div class="row wrap"><select id="compare-left" aria-label="比较方案一">${ps.map(p=>`<option value="${esc(p.id)}" ${p.id===left.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="micro">与</span><select id="compare-right" aria-label="比较方案二">${ps.map(p=>`<option value="${esc(p.id)}" ${p.id===right.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>${left.inputHash!==right.inputHash?`<div class="notice" style="margin:12px 0">${icon('info')}<span>两方案输入不同；以下仅为描述性对照，不可把差异全部归因于某一种策略。</span></div>`:''}<div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>指标</th><th>${esc(left.name)}</th><th>${esc(right.name)}</th></tr></thead><tbody>${[['margin','核算收益 / 元'],['water','用水 / m³'],['labour','劳动 / 工日'],['nSurplus','氮余量 / kg N'],['energy','可食能量代理 / GJ']].map(([k,n])=>`<tr><td>${n}</td><td>${fmt(left.candidate.totals[k])}</td><td>${fmt(right.candidate.totals[k])}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="card" style="margin-top:18px"><div class="card-header"><h2>工作台更新记录</h2><span class="micro">本地审计轨迹 · 最近80条</span></div>${state.audit.length?`<div class="timeline">${state.audit.slice(0,12).map(a=>`<div class="timeline-item"><h4>${esc(a.action)}</h4><p>${esc(a.detail)}</p><small>${displayDate(a.at)}</small></div>`).join('')}</div>`:`<p class="micro">进行编辑、搜索、保存或更新数据后，这里会记录时间与动作。</p>`}</section>`;}
function sourceCard(mark,title,kind,text,meta,link){return `<div class="source-card"><div class="source-logo">${mark}</div><div><h3>${title} ${badge(kind,kind==='public'?'已获取公开数据':kind==='synthetic'?'虚拟演示':'尚未取得')}</h3><p>${text}</p><div class="source-meta">${meta}</div></div>${link?`<a class="small-button" href="${safeUrl(link)}" target="_blank" rel="noopener noreferrer">来源 ↗</a>`:''}</div>`;}
function dataPage(){const d=state.dataset,c=state.climate;return heading('每一项数据，都说明它从哪里来','公开数据不等于地面实测，地图细节不等于逐地块精度，未知的信息不伪装成已知。',`<button data-action="export-bundle">${icon('download')}导出项目包</button>`)+`<div class="cols"><section class="card"><div class="card-header"><h2>来源登记</h2><span class="eyebrow">DATA LINEAGE</span></div>${sourceCard('N','NASA POWER · 2025年历史气候',c?'public':'local','温度、降水、相对湿度、风速。区域网格数据，不是本地气象站；仅降水接入当前需水核算。',c?`${c.records.length} 个月 · 点位 109.17°E, 18.38°N<br>原始降水单位 mm/day；月总量 = 月平均日降水 × 当月天数。<br>获取 ${displayDate(c.retrievedAt)}`:'本地快照未成功加载；不会补造公开气候。',SOURCES.power)}${sourceCard('O','OpenStreetMap · 地理背景',state.context?'public':'local','道路、水系和土地覆盖等地图要素。不是经营权、地籍或经调查的农田边界。',state.context?`${state.context.features.length} 个要素 · 本地矢量快照 · ODbL 1.0<br>获取 ${displayDate(state.context.retrievedAt)}`:'未取得本地矢量时只显示坐标网格；在线底图需网络。',SOURCES.osm)}${sourceCard('S','Sentinel-2 L2A · 2025-03-22','public','10m原始真彩色；本地影像已重投影至EPSG:3857。只用于背景对照，不据此声称真实作物或权属。',state.imagery?`场景 ${esc(state.imagery.itemId)}<br>获取 ${displayDate(state.imagery.retrievedAt)} · 单景历史，不是实时`:'正在载入影像元数据。','https://planetarycomputer.microsoft.com/dataset/sentinel-2-l2a')}${sourceCard('F','FTW / PRUE · 2025 预测单元','public','从已下载1170个空间单元中，按统一条件保留110个完整源几何。不是地籍，不保证逐地块准确。','面积≥0.1ha；完整位于影像内；与OSM农业斑块叠合≥90%。<br>叠合是筛选条件，不是精度或置信度。','https://source.coop/ftw/global-data')}${sourceCard('D','经营、资源与生产系数','synthetic',`${d.villages.length} 个假设协作组、${d.farms.length} 个假设主体。作物、家禽、配额、成本及响应系数均为演示假设。`,`真实作物、经营权、土壤值保留未知。<br>数据 ${esc(d.version)} · CRS ${esc(d.crs)}`,null)}<p class="micro">OSM 矢量按 ODbL 使用并保留归属。FTW 矢量按 CC-BY-4.0 使用；Copernicus 保留影像归属。真实边界精度、农户和土壤资料均尚未核验。</p></section><div class="stack"><section class="card"><div class="card-header"><h2>数据工具</h2>${badge('local','本机工作区')}</div><div class="actions-grid"><button data-action="export-bundle">${icon('download')}备份整个项目</button><button data-action="import-data">${icon('upload')}导入资源 / 项目</button><button data-action="export-geojson">${icon('map')}导出 GeoJSON</button><button data-action="download-template">${icon('file')}下载结构模板</button><button data-action="export-weather" ${!c?'disabled':''}>${icon('download')}气象数据 CSV</button><button data-action="refresh-weather">${icon('refresh')}重新获取气象</button></div><input type="file" id="import-file" accept=".json,.geojson,application/json" hidden><p class="micro">支持完整项目备份、标准资源 JSON，或更新已有地块的完整属性 GeoJSON。导入前进行结构、坐标、面积、主体关联和配额检查；不能代替地理数据质量核验。</p><div class="note-block">导入与编辑只写入当前浏览器。首次访问取得仓库里的公开快照，之后可离线使用模型；在线地图及重新获取气象仍需网络。私密农户资料不要提交到公共仓库。</div></section><section class="card"><div class="card-header"><h2>接入真实数据时</h2></div><div class="prose"><p><strong>先确定调查边界：</strong>经营主体、地块归属、时间窗口与资源共享规则。</p><p><strong>再替换参数：</strong>需水、用工、投入产出、价格、土壤差异、固定活动及可改变的安排。</p><p><strong>最后验证模型：</strong>独立数据检查、误差与敏感性分析、方案可实施性反馈。不是简单把虚拟标签改为实测标签。</p><p>高德地图未默认接入：当前统一使用 WGS84，未使用或公开任何 API 密钥。后续接入时需单独处理授权、坐标转换和来源合规。</p></div></section></div></div><section class="card" style="margin-top:18px"><div class="card-header"><div><h2>原始统计口径可检查</h2><p>NASA POWER · 2025年完整历史，不是2026年实时天气</p></div><a href="./data/public/nasa-power-2025-raw.json" target="_blank">原始 JSON ↗</a></div>${c?`<div class="table-wrap"><table><thead><tr><th>月份</th><th>温度 °C</th><th>平均日降水 mm/day</th><th>月降水 mm</th><th>湿度 %</th><th>风速 m/s</th></tr></thead><tbody>${c.records.map(r=>`<tr><td>${esc(r.month)}</td>${['temperatureC','precipitationMmDay','precipitationMmMonth','humidityPct','windMps'].map(k=>`<td class="number">${fmt(r[k],2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<p>公开数据尚不可用。</p>'}</section>`;}

function evidencePage(){const q=state.evidence,im=state.imagery;return heading('空间信息，要经得起追问。','结构检查不等于现场精度；来源、处理、假设与限制全部可以追溯。',`<button data-action="export-qc">${icon('download')}导出质控记录</button>`)+`<div class="evidence-headline"><div><span class="eyebrow">REPRODUCIBLE SELECTION</span><h2>从源数据到研究窗口，没有手工编造的边界。</h2><p>以下检查针对随 v${VERSION} 发布的基线源快照。用户导入或修改的资料需另行核验。</p></div><span class="tag public">${q?q.checks.filter(c=>c.passed).length:'—'} 项结构检查</span></div><div class="selection-pipeline"><div><small>01 / SOURCE</small><b>${fmt(q?.sourceCount)}</b><span>已下载 FTW 预测单元</span></div><i>→</i><div><small>02 / RULES</small><b>0.1 ha / 90%</b><span>面积门槛 / OSM 叠合门槛</span></div><i>→</i><div><small>03 / RETAINED</small><b>${fmt(q?.selectedCount)}</b><span>原始几何 · 不重画、不切分</span></div></div><div class="cols equal"><section class="card"><div class="card-header"><div><div class="eyebrow">GEOMETRY CHECKS</div><h2>几何与数据结构检查</h2></div>${badge('public','非田间精度报告')}</div>${q?q.checks.map(c=>`<div class="qc-row"><span class="qc-check ${c.passed?'':'fail'}">${icon(c.passed?'check':'close')}</span><div><strong>${esc(c.name)}</strong><p>${esc(c.detail)}</p></div></div>`).join(''):'<p>读取报告中…</p>'}</section><section class="card"><div class="card-header"><div><div class="eyebrow">IMAGE + SEMANTICS</div><h2>不要把分辨率误当作真实性</h2></div></div><dl class="evidence-dl spacious"><div><dt>Sentinel-2 获取日期</dt><dd>2025-03-22</dd></div><div><dt>原始像元分辨率</dt><dd>10 m，不代表10m田界精度</dd></div><div><dt>影像显示投影</dt><dd>EPSG:3857</dd></div><div><dt>几何 / 面积</dt><dd>WGS84 / 椭球面积</dd></div><div><dt>局部 SCL 可用分类比例</dt><dd>${fmt(im?im.localUsableFraction*100:null,2)}%</dd></div><div><dt>预测质量字段缺失</dt><dd>${fmt(q?.confidenceMissing)} / ${fmt(q?.selectedCount)}</dd></div><div><dt>现场田界 / 作物 / 权属</dt><dd class="unknown">未核验</dd></div></dl><div class="note-block">SCL 的4、5、6、7类按本次规则计为可用；不是无云概率，也不是每个单元观测准确率。FTW 的质量字段来自500m区域层，不解释为逐块正确概率；本窗口字段全部缺失，显示“—”。</div><div class="note-block">OSM斑块与FTW可能共享影像信息；两者叠合不是独立真值验证。筛选会排除未被OSM覆盖的小农田，因此不用于区域总量估计或代表性抽样。</div></section></div><section class="card" style="margin-top:20px"><div class="card-header"><h2>源文件与处理记录</h2><a href="./docs/SOURCES.md" target="_blank">数据许可与来源 ↗</a></div><div class="table-wrap"><table><thead><tr><th>文件</th><th>SHA-256（文件一致性）</th></tr></thead><tbody>${Object.entries(q?.sourceHashes||{}).map(([k,v])=>`<tr><td><a href="./data/evidence/${esc(k)}" target="_blank">${esc(k)} ↗</a></td><td class="mono hash-cell">${esc(v)}</td></tr>`).join('')}</tbody></table></div><p class="micro">原始数据保留；tools/prepare_evidence.py 记录投影、筛选、面积及几何检查。源产品为FTW/PRUE CC-BY-4.0；OSM ODbL；Copernicus Sentinel原归属保留。</p></section>`;}
function releaseModal(){const r=state.release;openModal('版本与更新记录',`<div class="release-header"><span class="release-number">v${VERSION}</span><div><strong>Research Routes</strong><p>研究预览 · 2026-09-30</p></div></div><dl class="evidence-dl spacious"><div><dt>应用版本</dt><dd>${VERSION}</dd></div><div><dt>农场模型版本</dt><dd>${MODEL_VERSION}</dd></div><div><dt>农场默认数据版本</dt><dd class="mono">${DATA_VERSION}</dd></div><div><dt>区域来源审计版本</dt><dd class="mono">${REGIONAL_EVIDENCE_VERSION}</dd></div><div><dt>构建源提交</dt><dd class="mono">${esc(r?.commit||'本地预览')}</dd></div></dl><div class="release-changes">${(r?.changes||['并列保留两条研究路线','展示官方省级背景与数据审计','保持农场模型和区域数据分离']).map(x=>`<p>${icon('check')}${esc(x)}</p>`).join('')}</div><p class="micro">当前版本沿用 v0.2 浏览器工作区；已有方案和反馈不会因新增路线页被覆盖。区域来源审计不进入农场模型。</p><div class="row wrap"><a href="./CHANGELOG.md" target="_blank">完整更新日志 ↗</a><button type="button" data-action="export-legacy">导出 v0.1 本地资料</button></div>`,null,'关闭');}
function guidePage(){return heading('一个可解释、可替换、可检验的研究原型','平台是载体，研究贡献来自模型关系、决策边界与对现实结果的检验。')+warning()+`<div class="guide-steps"><div class="guide-step"><b>01</b><h3>Mapping</h3><p>公开预测几何与历史气候；真实属性待调查。</p></div><div class="guide-step"><b>02</b><h3>Modelling</h3><p>生产组合、投入产出与系统边界。</p></div><div class="guide-step"><b>03</b><h3>Exploration</h3><p>多目标候选搜索与逐月约束。</p></div><div class="guide-step"><b>04</b><h3>Feedback</h3><p>保存方案、录入结果、保留版本。</p></div></div><div class="cols equal"><section class="card prose"><h2>这版做到了什么，又没有做到什么</h2><p>这是面向数字孪生的<strong>空间决策支持研究原型</strong>。已经有真实公开数据、虚拟经营对象、可计算的系统模型、方案快照和反馈记录；尚未与真实经营主体建立持续校准的动态对应。</p><p>不是成熟数字孪生、实时农业监测系统、经田间验证的 FarmDESIGN 或 FarmSTEPS，也不是这些模型的官方实现。</p><h3>多尺度不是地图缩放</h3><p>范围可选单主体、假设典型案例、多主体、假设协作组及演示窗口。独立模式按户限制资源；协作模式只共享所选同组成员资源；集中情景合并所选主体。没有纳入的主体不会贡献配额。协作是假设，不代表真实水权、经营权或参与同意。</p><h3>时间边界</h3><p>每次核算针对2025年选定季度中的3个月。所有生产系数都按一个<strong>演示核算窗口</strong>定义，不对应已核实的真实作物生育期。切换季度只改变气候输入，不代表已模拟作物状态、轮作衔接、库存和跨年投资。</p><h3>固定与可调整</h3><p>本版基线仅演示年生作物与假设家禽；模型亦支持用户提供的固定果园和鱼塘，其规模不被搜索擅自改变。其余地块在水稻、蔬菜、豆类、覆盖作物四种离散活动之间选择。没有考虑部分面积调整、复杂套作、多季种植和设施投资。</p><h3>五个研究维度的覆盖</h3><p>核算收益、资源需求和氮收支已有原型。平衡偏好按候选集归一化：收益0.45、节水0.20、氮收支余量绝对值0.15、食物能量0.20；这是显式偏好，非科学结论。可食能量仅为食物保障代理；劳动与参与底线仅反映部分社会条件；氮余量不是完整环境评价。无法把这些代理量直接称作已验证的全部五类绩效。</p></section><section class="card prose"><h2>模型公式与关键假设</h2><h3>收入与成本</h3><p><code>活动收入 = 面积 × 单位面积收入 × 土壤因子 × 冲击因子 × 价格倍率</code></p><p><code>核算收益 = 产品收入 − 基础成本 − 矿质氮费用 − 用水费 − 劳动价值 − 粪肥转移费</code></p><p>用水0.35元/m³，劳动100元/工日，矿质氮8元/kg N，内部粪肥转移2元/kg N，均为虚拟参数。基础成本不再包含这些单列费用；不计地租、固定资产折旧和完整资金流。</p><h3>水与劳动</h3><p><code>月需水 = 面积 × max(0, 参考需水 × 月份比例 − 月降水 × 10 × 有效比例)</code></p><p>1 mm降水落在1 ha上为10 m³。有效降水比例：种植0.35、水产0.15（示意）。每个月都检查资源需求 ≤ 对应边界内可用配额，不把季度总量可行当成每月可行。</p><h3>氮资源与系统边界</h3><p>家禽粪肥回收率0.65，当窗口有效率0.45；不足部分用矿质肥补齐。粪肥先自用，再在允许的组内转移。转移是内部流，不再计入整体外部输入。</p><p><code>系统氮余量 = 矿质肥 + 外购饲料氮 + 生物固氮 − 产品氮输出</code></p><p>未施用粪肥及土壤 / 储存变化未被独立分解；负余量可能表示土壤消耗或参数不一致，不能解释为环境负担为零。当前排序使用氮余量绝对值，是可修改的示意偏好。</p><h3>候选搜索与可复现</h3><p>可调整地块≤5时完整枚举当前离散集；更大问题采用固定种子的随机候选与局部邻域探索。显示的非支配集只相对于已检验候选，不宣称真实全局最优。最多展示排序后的36个候选。</p><p>每户参与底线：<code>新收益 ≥ 基准收益 − (1−比例) × |基准收益|</code>，避免负基准直接乘比例产生错误解释。</p></section></div><section class="card prose" style="margin-top:18px"><div class="card-header"><h2>下一阶段的接入位置</h2><a href="./docs/METHODS.md" target="_blank">完整方法说明 ↗</a></div><p><code>src/data.js</code>：对象结构、虚拟数据与参数；<code>src/model.js</code>：核算、边界、搜索；<code>src/optimizer.worker.js</code>：隔离计算；<code>src/map.js</code>：地图视图；<code>src/app.js</code>：研究工作流。</p><p>可把经校准的Python/R模型放到未来后端，以版本化JSON作为输入输出接口，不必将全部科研计算重写进网页。PhD1提供的种植系统、作物序列与实验响应需经过口径对齐后接入，而非当作现成已接入的数据。</p><p>后续优先验证：真实经营权与资源边界、地块与季节差异、种养关联、约束与利益分配、误差和敏感性。再决定是否引入连续状态更新、优化求解器、权限与共享数据库。</p><p>公开资源：<a href="${SOURCES.power}" target="_blank" rel="noopener">NASA POWER</a> · <a href="${SOURCES.gibs}" target="_blank" rel="noopener">NASA GIBS</a> · <a href="${SOURCES.osm}" target="_blank" rel="noopener">OpenStreetMap 归属与许可</a> · <a href="${SOURCES.repository}" target="_blank" rel="noopener">完整代码</a>。</p></section>`;}
function render(){map?.destroy();map=null;const pageFns={research:researchPage,overview:overviewPage,resources:resourcesPage,analysis:analysisPage,planner:plannerPage,feedback:feedbackPage,data:dataPage,evidence:evidencePage,guide:guidePage};let body;try{body=pageFns[state.page]();}catch(e){body=heading('当前输入无法计算','数据未被删除，请检查或重新导入。')+`<section class="card"><div class="notice error">${esc(e.message)}</div><button style="margin-top:16px" data-action="reset-demo">恢复演示资源（保留方案）</button><button data-action="export-bundle">先导出备份</button></section>`;}
 root.innerHTML=`<div class="shell ${state.menu?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#overview"><img src="./icon.svg" alt=""><div><strong>FarmSystem</strong><span>DESIGN WORKSPACE</span></div></a><div class="nav-label">RESEARCH WORKSPACE</div><nav class="nav" aria-label="主要导航">${Object.entries(PAGES).map(([k,v])=>`<button data-nav="${k}" class="${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}>${icon(v[0])}${v[1]}${state.page===k?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="pilot-card">${icon('leaf')}<strong>让每一种安排都有依据</strong><p>Hainan · Tropical systems<br>地图 → 系统 → 决策 → 反馈</p></div><div class="account"><div class="avatar">F</div><div><strong>空间决策研究原型</strong><button class="version-badge" data-action="version" aria-label="查看版本与更新日志">v${VERSION} <span>更新日志 ↗</span></button></div></div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" data-action="menu" aria-label="打开导航菜单">${icon('menu')}</button><div class="breadcrumbs"><span class="mono">FARMSYSTEM / RESEARCH</span><span>/</span><b>${PAGES[state.page][1]}</b></div><div class="top-actions"><div class="language-switch" role="group" aria-label="显示语言"><button data-language="zh" data-i18n-skip aria-label="中文" aria-pressed="${language==='zh'}">中文</button><button data-language="en" data-i18n-skip aria-label="English" aria-pressed="${language==='en'}">EN</button><button data-language="both" data-i18n-skip aria-label="Bilingual / 中英双语" aria-pressed="${language==='both'}">中/EN</button></div><button class="top-version" data-action="version">v${VERSION}</button><span class="top-status"><i class="status-dot"></i>本地工作区 · 无云同步</span><button class="top-source" data-nav="data">${icon('database')}数据来源</button><button class="top-export" data-action="export-bundle" aria-label="导出项目">${icon('download')}<span>导出项目</span></button></div></header><main class="main" id="main-content">${state.storageError?'<div class="notice error">本地保存失败：当前修改可能仅在内存中，请导出项目备份。</div>':''}${body}<footer class="footer"><span>${icon('shield')}源几何、建模假设与计算结果分开记录</span><span>FarmSystemDesign v${VERSION} · 模型 ${MODEL_VERSION} · 浏览器本地工作区</span></footer></main></div></div>`;
 const el=document.querySelector('#farm-map');if(el){map=new FarmMap(el,{data:state.dataset,context:state.context,imagery:state.imagery,selectedIds:ids(),selectedPlot:state.selectedPlot,onSelect:id=>{state.selectedPlot=id;const panel=document.querySelector('#object-inspector');if(panel){panel.innerHTML=plotDetail();applyLanguage(panel,language);}else{const old=document.querySelector('.detail-card');if(old){old.outerHTML=plotDetail();applyLanguage(root,language);}}},onView:v=>state.view=v,allocation:state.preview?.candidate?.allocation||null,theme:state.theme,basemap:state.basemap,showResources:state.showResources,view:state.view,opacity:state.opacity,osmPatches:state.osmPatches,allFields:state.allFields,showOSM:state.showOSM,showAllFields:state.showAllFields});}
 setLanguage(language);
}
function openModal(title,content,submit,button='保存'){modal.innerHTML=`<form id="modal-form"><div class="modal-header"><h2>${title}</h2><button type="button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${content}<p id="form-error" class="micro" style="color:#b66754"></p><div class="modal-footer"><button type="button" data-action="close-modal">取消</button><button class="primary" type="submit">${button}</button></div></form>`;applyLanguage(modal,language);modal.showModal();modal.querySelector('form').onsubmit=e=>{e.preventDefault();try{const result=submit?submit(new FormData(e.currentTarget)):true;if(result!==false)modal.close();}catch(err){modal.querySelector('#form-error').textContent=err.message;}};}
function selectedCandidate(){return state.results?.candidates.find(c=>c.id===state.candidateId)||state.results?.candidates[0];}
function savePlan(){if(stale())return toast('输入已变化，请重新运行。');const candidate=selectedCandidate();if(!candidate)return;openModal('保存方案快照',`<div class="field"><label for="plan-name">方案名称</label><input id="plan-name" name="name" required maxlength="70" value="${esc(`情景方案 ${state.plans.length+1} · Q${state.config.quarter+1}`)}"></div><div class="note-block">保存完整输入、结果、边界与模型版本。不更新地块现状，也不代表已采用。最多保留30个快照，建议定期导出。</div>`,fd=>{if(state.plans.length>=30)throw new Error('方案库已达30个。请导出并删除不需要的快照。');const r=state.results;const plan={id:uid(),name:String(fd.get('name')).trim(),createdAt:now(),status:'draft',dataset:structuredClone(state.dataset),climate:structuredClone(state.climate),config:structuredClone(r.config),farmIds:[...r.farmIds],candidate:structuredClone(candidate),baseline:structuredClone(r.baseline),applicationVersion:VERSION,dataVersion:state.dataset.version,buildCommit:state.release?.commit||null,modelVersion:r.modelVersion,inputHash:r.inputHash};if(!plan.name)throw new Error('请输入名称');state.plans.unshift(plan);if(!audit('保存方案',`${plan.name} · 输入 ${plan.inputHash}`)){state.plans.shift();throw new Error('本地存储失败，方案未保存。请导出当前搜索结果并清理旧快照。');}toast('已保存在本地方案库，未覆盖现状。');render();});}
function editPlot(id){const p=state.dataset.plots.find(p=>p.id===id);if(!p)return;const fixed=p.locked||!CROPS[p.crop].annual;openModal(`编辑 ${esc(p.name)}`,`<div class="notice">${icon('info')}<span>几何来源仍为 ${p.geometrySource==='public-ml-prediction'?'公开模型预测（未地面核验）':p.geometrySource==='synthetic'?'虚拟':'用户数据'}。录入值不自动被核验为实测。</span></div><div class="form-grid" style="margin-top:15px"><div><label>假设基准活动 ${fixed?'（固定）':''}</label><select name="crop">${Object.entries(CROPS).filter(([k,c])=>fixed?k===p.crop:c.annual).map(([k,c])=>`<option value="${k}" ${k===p.crop?'selected':''}>${c.name}</option>`).join('')}</select></div><div><label>产出因子 · 示例参数</label><input name="soilFactor" type="number" min="0.1" max="3" step="0.01" required value="${p.soilFactor}"></div><div class="span-2"><label>来源 / 备注</label><textarea name="note" maxlength="500">${esc(p.note)}</textarea></div></div>`,fd=>{const next=structuredClone(state.dataset),q=next.plots.find(x=>x.id===id);q.crop=String(fd.get('crop'));q.soilFactor=Number(fd.get('soilFactor'));q.note=String(fd.get('note'));q.provenance='user-unverified';next.version=`local-${now()}`;const errors=validateDataset(next);if(errors.length)throw new Error(errors.join('；'));state.dataset=next;audit('修改活动假设',`${id} · 仅本地 · 几何来源未改变`);render();toast('假设已更新；公开几何和已保存方案快照不变。');});}
function editFarm(id){const f=state.dataset.farms.find(f=>f.id===id);if(!f)return;openModal(`编辑 ${esc(f.name)} 的资源`, `<p class="micro">以下配额用于每个三个月演示窗口；不是按真实季节分别调查的资源表。</p><div class="form-grid" style="margin-top:14px">${['water','labour'].flatMap(k=>f[k].map((v,i)=>`<div><label>窗口第${i+1}月${k==='water'?'水配额 m³':'劳动配额 工日'}</label><input name="${k}${i}" type="number" min="0" step="0.01" required value="${v}"></div>`)).join('')}<div><label>固定家禽数量 / 只</label><input name="poultry" type="number" min="0" step="1" required value="${f.poultry}"></div></div>`,fd=>{const next=structuredClone(state.dataset),x=next.farms.find(x=>x.id===id);for(const k of ['water','labour'])x[k]=[0,1,2].map(i=>Number(fd.get(`${k}${i}`)));x.poultry=Number(fd.get('poultry'));x.provenance='user-unverified';next.version=`local-${now()}`;const errors=validateDataset(next);if(errors.length)throw new Error(errors.join('；'));state.dataset=next;audit('修改资源配额',`${id} · 用户录入未核验`);render();});}
function selectGroup(){openModal('选择共同参与分析的主体',`<p class="micro">选中只表示参与当前分析，不代表现实中已同意共享资源。</p><div class="select-grid" style="margin-top:14px">${state.dataset.farms.map(f=>`<label class="select-item"><input type="checkbox" name="farms" value="${esc(f.id)}" ${state.scopeIds.includes(f.id)?'checked':''}><span><strong>${esc(f.name)}</strong><small>${esc(f.id)} / ${esc(f.villageId)}</small></span></label>`).join('')}</div>`,fd=>{const selected=fd.getAll('farms');if(!selected.length)throw new Error('至少选择一个主体');state.scopeIds=selected;state.view=null;state.selectedPlot=plots()[0].id;render();},'应用范围');}
function addObservation(){if(!state.plans.length)return toast('请先保存一个方案，再记录与之对应的反馈。');openModal('记录方案反馈',`<div class="form-grid"><div class="span-2"><label>对应方案及其相同核算窗口</label><select name="planId">${state.plans.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · 2025 Q${p.config.quarter+1} / ${p.farmIds.length}主体</option>`).join('')}</select></div><div><label>记录指标（同口径）</label><select name="metric"><option value="water">全部所选主体窗口用水 / m³</option><option value="revenue">全部所选主体窗口销售收入 / 元</option></select></div><div><label>结果数值</label><input name="value" type="number" min="0" step="0.01" required></div><div><label>结果日期</label><input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></div><div><label>数据身份</label><select name="provenance"><option value="synthetic">虚拟反馈 · 流程练习</option><option value="user-unverified">用户录入 · 尚未核验</option></select></div><div class="span-2"><label>来源、统计范围与可比性说明（必填）</label><textarea name="note" required maxlength="700" placeholder="说明对应哪些对象、哪段时间、数据来源；不能用单日数据比较整个窗口。"></textarea></div><label class="span-2 row"><input name="sameScope" type="checkbox" required>确认采用所选方案相同的对象、时间窗口和指标口径；虚拟记录也保持口径一致。</label></div>`,fd=>{const p=state.plans.find(p=>p.id===fd.get('planId')),value=Number(fd.get('value'));if(!p||!Number.isFinite(value)||value<0)throw new Error('输入无效');const metric=String(fd.get('metric'));state.observations.unshift({id:uid(),planId:p.id,planName:p.name,period:`2025 Q${p.config.quarter+1} / ${p.farmIds.length}个主体`,metric,value,predicted:p.candidate.totals[metric],date:String(fd.get('date')),note:String(fd.get('note')),provenance:String(fd.get('provenance')),recordedAt:now()});audit('添加反馈记录',`${p.name} · ${String(fd.get('provenance'))} · 不自动改写模型`);render();});}
function runSearch(){if(state.running)return;state.running=true;state.progress=0;render();worker=new Worker(new URL('./optimizer.worker.js',import.meta.url),{type:'module'});worker.onmessage=event=>{const m=event.data;if(m.type==='progress'){state.progress=m.progress;const bar=root.querySelector('.progress span');if(bar)bar.style.width=`${m.progress}%`;}if(m.type==='result'){state.results=m.result;state.candidateId=m.result.candidates[0]?.id||null;state.running=false;worker.terminate();worker=null;audit('完成候选搜索',`${m.result.evaluated} 个候选 / ${m.result.feasibleCount} 个可行 · ${m.result.inputHash}`);render();toast(m.result.candidates.length?'搜索完成：请比较方案，而非只看排序。':'本次未找到可行方案，请检查边界和约束。');}if(m.type==='error'){state.running=false;worker?.terminate();worker=null;render();toast(`计算失败：${m.error}`);}};worker.onerror=e=>{state.running=false;worker?.terminate();worker=null;render();toast(`计算线程失败：${e.message}`);};worker.postMessage({dataset:state.dataset,farmIds:ids(),config:state.config,climate:state.climate});}
function projectBundle(){return {application:'FarmSystemDesign',schemaVersion:1,exportedAt:now(),version:VERSION,modelVersion:MODEL_VERSION,dataVersion:state.dataset.version,regionalEvidenceVersion:REGIONAL_EVIDENCE_VERSION,buildCommit:state.release?.commit||null,dataset:state.dataset,climate:state.climate,plans:state.plans,observations:state.observations,audit:state.audit,disclaimer:'Public context, synthetic farm records, user entries and uncalibrated model results must remain distinguishable. Browser-local data only.'};}
function validateClimate(c){if(c===null)return true;if(!c||!Array.isArray(c.records)||c.records.length!==12)return false;return c.records.every((r,i)=>r.month===`2025-${String(i+1).padStart(2,'0')}`&&['temperatureC','precipitationMmDay','precipitationMmMonth','humidityPct','windMps'].every(k=>r[k]===null||Number.isFinite(r[k])));}
async function importFile(file){if(!file)return;if(file.size>12*1024*1024)return toast('文件超过12MB，请拆分或使用后续后端数据接口。');try{const raw=JSON.parse(await file.text());let d=raw.dataset||raw;if(raw.type==='FeatureCollection'){d=structuredClone(state.dataset);if(!Array.isArray(raw.features)||!raw.features.length)throw new Error('GeoJSON 没有要素');const seen=new Set();for(const feature of raw.features){const p=feature.properties,id=p?.id||feature.id;if(!id||seen.has(id))throw new Error('GeoJSON ID缺失或重复');seen.add(id);const i=d.plots.findIndex(p=>p.id===id);if(i<0)throw new Error(`未知地块 ${id}：新增主体 / 地块请使用完整资源模板，不能自动编造其经营配额。`);d.plots[i]={...d.plots[i],...p,id,geometry:feature.geometry};}d.version=`import-${now()}`;}
 const errors=validateDataset(d);if(errors.length)throw new Error(errors.slice(0,8).join('；'));const bundle=raw.application==='FarmSystemDesign';if(bundle){if(!validateClimate(raw.climate))throw new Error('项目气候数据结构不匹配');if(!Array.isArray(raw.plans)||raw.plans.length>30||!Array.isArray(raw.observations)||!Array.isArray(raw.audit))throw new Error('项目备份记录结构不匹配');for(const p of raw.plans){if(!p.id||!p.name||!p.candidate?.totals||!p.candidate?.allocation||!Array.isArray(p.farmIds)||!p.config||validateDataset(p.dataset).length)throw new Error('方案快照结构不完整');for(const k of ['margin','water','labour','nSurplus','energy'])if(!Number.isFinite(p.candidate.totals[k]))throw new Error('方案结果必须为有限数值');}}
 openModal('确认导入',`<div class="notice">${icon('info')}<span>将替换当前资源：${d.farms.length} 个主体、${d.plots.length} 个地块。${bundle?'完整项目备份也会替换当前方案、反馈和更新记录。':'现有方案保留原快照，不自动跟随变化。'}请先导出当前备份。</span></div><p class="micro">结构校验通过不等于来源和现实精度已核验。导入数据按其声明保留身份；用户声明实测仍显示“未核验”。</p>`,()=>{state.dataset=d;if(bundle){state.climate=raw.climate;state.plans=raw.plans;state.observations=raw.observations;state.audit=raw.audit;}state.scope='region';state.scopeIds=[];state.selectedPlot=d.plots[0].id;state.view=null;state.results=null;state.preview=null;audit('导入资源',`${file.name} · ${d.farms.length}主体 / ${d.plots.length}地块 · 结构已检查，来源未核验`);render();toast('导入完成，只保存在本浏览器。');},'确认替换');
 }catch(e){toast(`导入失败，原数据未改变：${e.message}`);}}
async function refreshWeather(){toast('正在重新获取2025年历史气象，原快照暂时保留。');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const url='https://power.larc.nasa.gov/api/temporal/monthly/point?parameters=T2M,PRECTOTCORR,RH2M,WS2M&community=AG&longitude=109.17&latitude=18.38&start=2025&end=2025&format=JSON';const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw new Error(`HTTP ${response.status}`);const raw=await response.json(),p=raw.properties?.parameter;if(!p?.PRECTOTCORR)throw new Error('NASA响应格式异常');const records=Array.from({length:12},(_,i)=>{const month=`2025-${String(i+1).padStart(2,'0')}`,k=month.replace('-',''),value=(key)=>Number.isFinite(p[key]?.[k])&&p[key][k]>-900?p[key][k]:null,precipitationMmDay=value('PRECTOTCORR');return {month,temperatureC:value('T2M'),precipitationMmDay,precipitationMmMonth:precipitationMmDay===null?null:Math.round(precipitationMmDay*new Date(2025,i+1,0).getDate()*100)/100,humidityPct:value('RH2M'),windMps:value('WS2M')};});const c={id:'nasa-power-2025',status:'public-gridded',source:'NASA POWER / MERRA-2',sourceUrl:url,documentation:SOURCES.power,retrievedAt:now(),year:2025,requestedPoint:[109.17,18.38],geometry:raw.geometry,header:raw.header,parameters:raw.parameters,records};if(!validateClimate(c))throw new Error('数据校验失败');state.climate=c;audit('更新公开气候','NASA POWER 2025历史数据 · 仍不是实时天气');render();toast('公开历史数据已更新，旧方案快照不变。');}catch(e){toast(`获取失败，继续使用原快照：${e.name==='AbortError'?'网络超时':e.message}`);}finally{clearTimeout(timeout);}}
function selectPlot(id){state.selectedPlot=id;const p=state.dataset.plots.find(x=>x.id===id);if(p){state.view={center:centroid(p),zoom:16};}render();}
root.addEventListener('click',event=>{const b=event.target.closest('[data-nav],[data-action],[data-basemap],[data-scenario],[data-resource-tab],[data-candidate],[data-research-track],[data-language]');if(!b||b.disabled)return;const ds=b.dataset;
 if(ds.language){language=ds.language;setLanguage(language);return;}
 if(ds.nav)return navigate(ds.nav);
  if(ds.researchTrack){state.researchTrack=ds.researchTrack;render();return;}
 if(ds.basemap){state.basemap=ds.basemap;map?.setBasemap(ds.basemap);root.querySelectorAll('[data-basemap]').forEach(b=>b.classList.toggle('active',b.dataset.basemap===ds.basemap));return;}
 if(ds.resourceTab){state.resourceTab=ds.resourceTab;state.query='';render();return;}
 if(ds.candidate){state.candidateId=ds.candidate;render();return;}
 if(ds.scenario){state.config={...state.config,...SCENARIOS[ds.scenario],scenario:ds.scenario};delete state.config.name;render();return;}
 const id=ds.id,p=state.plans.find(x=>x.id===id);switch(ds.action){
 case 'version':releaseModal();break;
 case 'export-qc':if(state.evidence)download(`FarmSystem-v${VERSION}-QC.json`,JSON.stringify(state.evidence,null,2));break;
  case 'export-research-audit':download(`FarmSystem-${state.researchTrack}-data-audit.csv`,csv(auditCsvRows(state.researchTrack)),'text/csv;charset=utf-8');break;
 case 'focus-plot':{const p=state.dataset.plots.find(p=>p.id===state.selectedPlot);if(p&&map?.map){map.map.fitBounds(map.L.geoJSON({type:'Feature',geometry:p.geometry}).getBounds(),{padding:[70,70],maxZoom:17,animate:true});}break;}

 case 'menu':state.menu=!state.menu;root.querySelector('.shell')?.classList.toggle('menu-open',state.menu);break;
 case 'run':runSearch();break;
 case 'cancel-run':worker?.terminate();worker=null;state.running=false;render();toast('计算已取消，没有生成新结果。');break;
 case 'save-plan':savePlan();break;
 case 'preview-candidate':{const c=selectedCandidate();if(c){state.preview={name:'当前候选方案',candidate:c};state.scope='group';state.scopeIds=[...state.results.farmIds];navigate('resources');}break;}
 case 'preview-plan':if(p){state.preview={name:p.name,candidate:p.candidate};state.scope='group';state.scopeIds=p.farmIds.filter(id=>state.dataset.farms.some(f=>f.id===id));if(!state.scopeIds.length){state.scope='region';state.preview=null;return toast('该快照的经营主体已不在当前数据中，请先导出快照查看。');}navigate('resources');toast('方案着色叠加在当前几何上；几何变化时请核对原快照。');}break;
 case 'exit-preview':state.preview=null;render();break;
 case 'edit-plot':editPlot(id);break;
 case 'edit-farm':editFarm(id);break;
 case 'select-plot':selectPlot(id);break;
 case 'plan-farm':state.scope='single';state.scopeIds=[id];state.preview=null;state.view=null;navigate('analysis');break;
 case 'select-group':selectGroup();break;
 case 'add-observation':addObservation();break;
 case 'intent-plan':if(p){p.status=p.status==='intended'?'draft':'intended';audit('更新方案意向',`${p.name} · ${p.status==='intended'?'拟采用（非实施证明）':'候选'}`);render();}break;
 case 'delete-plan':if(p)openModal('删除本地方案',`<p>删除「${esc(p.name)}」？已有反馈记录保留文字与数值，不会被删除。</p>`,()=>{state.plans=state.plans.filter(x=>x.id!==id);audit('删除方案',p.name);render();},'删除');break;
 case 'export-plan':if(p)download(`FarmSystem-plan-${p.id}.json`,JSON.stringify(p,null,2));break;
 case 'export-bundle':download(`FarmSystem-project-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(projectBundle(),null,2));toast('已导出项目包；其中可能包含你的本地私人数据，请妥善保管。');break;
 case 'export-geojson':download('FarmSystem-plots.geojson',JSON.stringify(toGeoJSON(state.dataset),null,2),'application/geo+json');break;
 case 'export-results':if(state.results)download('FarmSystem-search-result.json',JSON.stringify(state.results,null,2));break;
 case 'export-baseline':download('FarmSystem-resource-accounting.json',JSON.stringify({createdAt:now(),config:state.config,dataVersion:state.dataset.version,result:current()},null,2));break;
 case 'download-template':download('FarmSystem-resource-template.json',JSON.stringify(makeDemo(),null,2));break;
 case 'import-data':root.querySelector('#import-file')?.click();break;
 case 'refresh-weather':refreshWeather();break;
 case 'export-weather':if(state.climate)download('NASA-POWER-2025-monthly.csv',csv([['month','temperature_C','mean_daily_precip_mm_day','monthly_precip_mm','RH_percent','wind_m_s'],...state.climate.records.map(r=>[r.month,r.temperatureC,r.precipitationMmDay,r.precipitationMmMonth,r.humidityPct,r.windMps])]),'text/csv;charset=utf-8');break;
 case 'reset-demo':openModal('恢复演示资源','<p>当前资源将恢复为本版公开预测几何与显式假设参数；已存方案与反馈保留。请先导出当前项目。</p>',()=>{state.dataset=makeDemo();state.scope='region';state.scopeIds=[];state.results=null;state.preview=null;state.selectedPlot=state.dataset.plots[0].id;state.view=null;audit('恢复演示','资源恢复为v0.2公开预测几何与假设参数');render();},'恢复');break;
 }});
modal.addEventListener('click',e=>{if(e.target.closest('[data-action="export-legacy"]')){const raw=localStorage.getItem('farmsystem-workspace-v1');if(raw)download('FarmSystem-v0.1-local-backup.json',JSON.stringify({application:'FarmSystemDesign',schemaVersion:1,version:'0.1.0',...JSON.parse(raw)},null,2));else toast('当前浏览器没有v0.1工作区数据。');return;}if(e.target.closest('[data-action="close-modal"]'))modal.close();});
root.addEventListener('input',e=>{const t=e.target;if(t.id==='map-opacity'){state.opacity=Number(t.value)/100;map?.setOpacity(state.opacity);return;}if(t.id==='resource-search'){state.query=t.value;const el=root.querySelector('#resource-table');if(el)el.innerHTML=state.resourceTab==='plots'?plotTable():farmTable();}if(t.dataset.config){state.config[t.dataset.config]=Number(t.value)/100;state.config.scenario='custom';const out=root.querySelector(`#${t.id}-value`);if(out)out.textContent=`${fmt(Number(t.value))}%`;}});
root.addEventListener('change',e=>{const t=e.target;switch(t.id){
 case 'show-osm':state.showOSM=t.checked;render();break;
 case 'show-all-fields':state.showAllFields=t.checked;render();break;

 case 'scope':state.scope=t.value;state.scopeIds=t.value==='village'?[state.dataset.villages[0].id]:t.value==='single'?[state.dataset.farms[0].id]:t.value==='group'?state.dataset.farms.slice(0,4).map(f=>f.id):[];state.view=null;state.selectedPlot=plots()[0]?.id;state.preview=null;render();break;
 case 'scope-object':state.scopeIds=[t.value];state.view=null;state.selectedPlot=plots()[0]?.id;state.preview=null;render();break;
 case 'quarter':state.config.quarter=Number(t.value);render();break;
 case 'decision-mode':state.config.mode=t.value;render();break;
 case 'objective':state.config.objective=t.value;render();break;
 case 'participation':state.config.minIncomeRatio=Number(t.value);render();break;
 case 'show-resources':state.showResources=t.checked;render();break;
 case 'map-theme':state.theme=t.value;render();break;
 case 'compare-left':state.compareLeft=t.value;render();break;
 case 'compare-right':state.compareRight=t.value;render();break;
 case 'import-file':importFile(t.files[0]);t.value='';break;
 default:if(t.dataset.config)render();
 }});
root.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-candidate]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p in PAGES&&state.page!==p){state.page=p;render();}});

async function init(){observeLanguage();render();const get=async path=>{try{const r=await fetch(path);if(!r.ok)return null;return await r.json();}catch{return null;}};const [c,g,i,q,o,a,v]=await Promise.all([get('./data/public/climate.json'),get('./data/evidence/osm-context-v2.geojson'),get('./data/evidence/sentinel-imagery.json'),get('./data/evidence/quality-report.json'),get('./data/evidence/agricultural-evidence.geojson'),get('./data/evidence/ftw-fields-2025.geojson'),get('./version.json')]);if(!state.climate&&validateClimate(c))state.climate=c;state.context=g;state.imagery=i;state.evidence=q;state.osmPatches=o;state.allFields=a;state.release=v;state.loading=false;render();if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});}}
init();
